{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "stdにある「日銀とGPIFは国内株式の大口の保有者でもある」という重要な情報が抜け落ちており、stdの他の部分とは異なる内容（株価は選挙や政府の発表で動く、政治だけが原因ではない）に完全に書き換わっている。",
      "fix": "stdの内容に合わせて、日銀やGPIFなどの株保有に関する内容を盛り込むか、stdの要約として適切な内容に修正する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdでは「選挙や政策の発表で株価が動くことはあるのか。年金積立金も国内株式で運用されている」とあるが、hsでは年金についての話に大きく偏っており、stdにある「選挙や政策の発表で株価が動くのか」という問いが含まれていない。",
      "fix": "stdの内容（選挙・政策の発表と株価、年金積立金の運用）の両方が正しく伝わるように修正する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/text の hs",
      "detail": "stdでは「予想外の金融政策の発表に株価が反応することは多くの研究で確認されている」となっているが、hsでは「予想外の利下げのあとに株価が上がる傾向がみられました」と、「利下げ」というstdにない具体的な事象が追加されている。",
      "fix": "「利下げ」の具体的な言及を削除し、stdの「予想外の金融政策の発表に株価が反応する」という表現に戻す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/5/text の hs",
      "detail": "stdでは手法（イベント・スタディ等）を用いて影響を推定することに触れているが、hsでは手法のことが抜け落ち、一般的な株価の変動要因の説明になっている。",
      "fix": "stdの「特定の政治イベントの影響の推定にはイベント・スタディ等の手法が用いられる」という要素を盛り込むように修正する。"
    }
  ]
}
